                report['archives'].append({'path': str(p), 'sha256': expected, 'members': members, 'exact_members': len(z.namelist()) == 2 and members == expected_members, 'crc_ok': z.testzip() is None})
    elif p.suffix in {'.md', '.txt', '.py', '.json'}:
        lines = [s.strip()[:300] for s in raw.decode('utf-8').splitlines() if pattern.search(s)]
